"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6432],{16681:e=>{e.exports=JSON.parse('{"functions":[{"name":"CreateGround","desc":"A world pile.\\n\\nGets a bare CUID: a ground pile has no owner, so there is nothing to derive\\nan id from. Unlimited by default -- the ground has no stack limit.","params":[{"name":"stack","desc":"","lua_type":"ItemStack?"}],"returns":[{"desc":"","lua_type":"ItemHolder\\n"}],"function_type":"method","source":{"line":46,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}},{"name":"CreateSlot","desc":"A slot inside something.\\n\\nThe id is DERIVED: `{owner_id}_{slot_key}`. For an inventory the key is the\\nslot\'s allocation index; for equipment it is the equip type, which reads\\nstraight off the wire (`aB3f_Primary`). Either way the id is reproducible\\nfrom facts both realms already have, so replicating a slot costs the key\\nrather than an opaque string.\\n\\n`max_quantity` nil means unlimited -- that is the replacement for threading\\n`unlimited_stack` through every call.","params":[{"name":"owner_id","desc":"","lua_type":"string"},{"name":"slot_key","desc":"","lua_type":"string | number"},{"name":"max_quantity","desc":"","lua_type":"number?"},{"name":"accepts","desc":"","lua_type":"((config: ItemConfig) -> boolean)?\\n"}],"returns":[{"desc":"","lua_type":"ItemHolder\\n"}],"function_type":"method","source":{"line":69,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}},{"name":"CreateStack","desc":"","params":[{"name":"config","desc":"","lua_type":"ItemConfig"},{"name":"quantity","desc":"","lua_type":"number"},{"name":"durability","desc":"","lua_type":"number?"},{"name":"state","desc":"","lua_type":"Types.ItemState?\\n"}],"returns":[{"desc":"","lua_type":"ItemStack\\n"}],"function_type":"method","source":{"line":88,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}},{"name":"IsEmpty","desc":"","params":[{"name":"holder","desc":"","lua_type":"ItemHolder"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":107,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}},{"name":"AreMergeable","desc":"Two stacks merge only if every per-stack property matches. Durability and\\nskin differ per stack, so a damaged rifle must not silently absorb a pristine\\none -- today MoveQuantity only compares ClassName.","params":[{"name":"a","desc":"","lua_type":"ItemStack"},{"name":"b","desc":"","lua_type":"ItemStack"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":176,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}},{"name":"LimitFor","desc":"The stack limit that actually applies to `config` in this holder.\\n\\nnil means unbounded. Holder override first, then the item\'s own MaxQuantity --\\nso an item definition still sets the default stack size and a container can\\nraise or lower it. Shared with TransactionService, which needs the identical\\nrule against the projected state.","params":[{"name":"holder","desc":"","lua_type":"ItemHolder"},{"name":"config","desc":"","lua_type":"ItemConfig"}],"returns":[{"desc":"","lua_type":"number?\\n"}],"function_type":"method","source":{"line":196,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}},{"name":"Space","desc":"","params":[{"name":"holder","desc":"","lua_type":"ItemHolder"},{"name":"config","desc":"","lua_type":"ItemConfig"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"method","source":{"line":203,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}},{"name":"Weight","desc":"","params":[{"name":"holder","desc":"","lua_type":"ItemHolder"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"method","source":{"line":210,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}},{"name":"GroupWeight","desc":"","params":[{"name":"group","desc":"","lua_type":"HolderGroup"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"method","source":{"line":221,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}},{"name":"GroupSpace","desc":"How many more units of `config` the group can carry by weight.","params":[{"name":"group","desc":"","lua_type":"HolderGroup"},{"name":"config","desc":"","lua_type":"ItemConfig"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"method","source":{"line":234,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}},{"name":"Transfer","desc":"Move up to `quantity` from one holder to another.\\n\\nReturns what moved and what did not. THE REMAINDER STAYS IN `from` -- that\\nis the whole point. Picking up a 5,000 pile into 200 units of space leaves\\n4,800 on the ground rather than deleting them.\\n\\n`group` is the destination\'s weight context, if it has one.","params":[{"name":"from","desc":"","lua_type":"ItemHolder"},{"name":"to","desc":"","lua_type":"ItemHolder"},{"name":"quantity","desc":"","lua_type":"number?"},{"name":"group","desc":"","lua_type":"HolderGroup?\\n"}],"returns":[{"desc":"","lua_type":"TransferResult\\n"}],"function_type":"method","source":{"line":261,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}},{"name":"TransferToGroup","desc":"Move a stack into the first holders that will take it, in order.\\n\\nThis is the pickup path: try each slot, keep whatever will not fit in the\\nsource. Returns the total moved.","params":[{"name":"from","desc":"","lua_type":"ItemHolder"},{"name":"group","desc":"","lua_type":"HolderGroup"},{"name":"quantity","desc":"","lua_type":"number?\\n"}],"returns":[{"desc":"","lua_type":"TransferResult\\n"}],"function_type":"method","source":{"line":343,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}},{"name":"Split","desc":"Take `quantity` out as a free-standing stack.\\n\\nUsed for drag-and-drop and for dropping to the world: the caller owns the\\nreturned stack and must place it somewhere. Returns nil if nothing moved,\\nnever a zero-quantity stack.","params":[{"name":"holder","desc":"","lua_type":"ItemHolder"},{"name":"quantity","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"ItemStack?\\n"}],"function_type":"method","source":{"line":394,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}}],"properties":[],"types":[],"name":"HolderService","desc":"Operations over ItemHolders.\\n\\nEvery mutating function here is CONSERVATIVE: the total quantity across all\\nholders involved is identical before and after. Nothing is destroyed as a\\nconsequence of arithmetic. A holder that reaches zero becomes empty and\\nstays a holder -- removing a ground pile from the world is a separate,\\nexplicit decision, not a side effect of the last item being taken.\\n\\nContrast the current path, where BaseItem:SetQuantity clamps to the stack\\nlimit, discards the difference, and calls self:Destroy() at zero.","source":{"line":17,"path":"src2/shared/EmberSharedLibrary/GameShared/Inventory2/HolderService.luau"}}')}}]);